/**
 * FileUpload.Row: one file, with its status and its controls, playing its exit when it leaves.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/file-upload.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, type JSX } from 'solid-js'

import { Icon, claimSlot, elementRef, scope, watchEffect } from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/controls/file-upload.module.css'
import Button from './Button'
import Progress from '../structure/Progress'
import type { FileUploadItem } from './FileUpload'

export interface FileUploadRowProps {
  file: FileUploadItem
  /**
   * False once the file has left the list, while the row plays its exit.
   */
  open: boolean
  /**
   * The size, formatted by the messages.
   */
  size?: string
  /**
   * The app handles a retry, so a failed row offers one.
   */
  retryable: boolean
  /**
   * The field is disabled, and the row’s controls with it.
   */
  disabled: boolean
  retryLabel: string
  removeLabel: string
  progressLabel: string
  onRetry?: () => void
  onRemove?: () => void
  /**
   * The exit has played, and the member can drop the row.
   */
  onDone?: () => void
}

/** FileUpload.Row: one file, with its status and its controls, playing its exit when it leaves. */
export default function FileUploadRow(given: FileUploadRowProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const row = elementRef<HTMLElement>()
    const present = usePresence(
      () => props.open,
      () => row.value,
      'fileupload.row',
    )
    const effect1 = () => {
      void (present() || props.onDone?.())
    }
    watchEffect(
      createMemo(() => present()),
      effect1,
      false,
    )
    return (
      <li class={styles.row} data-status={props.file.status} ref={row.attach}>
        {/* rowIcon */}
        <span class={styles.rowIcon}>
          <Icon name="document" />
        </span>
        {/* details */}
        <span class={styles.details}>
          {/* name */}
          <span class={styles.name}>{props.file.name}</span>
          {props.size !== undefined ? <span class={styles.meta}>{props.size}</span> : null}
          {props.file.status === 'error' && props.file.message !== undefined ? (
            <span class={styles.message}>{props.file.message}</span>
          ) : null}
        </span>
        {props.file.status === 'uploading' ? (
          <span class={styles.trailing}>
            {/* progress */}
            <span class={styles.progress}>
              <Progress value={props.file.progress ?? 0} label={props.progressLabel} />
            </span>
            {/* percent */}
            <span class={styles.percent}>{`${Math.round(props.file.progress ?? 0)}%`}</span>
          </span>
        ) : null}
        {props.file.status === 'done' ? (
          <span class={styles.done}>
            <Icon name="success" />
          </span>
        ) : null}
        {props.file.status === 'error' && props.retryable ? (
          <Button
            variant="ghost"
            tone="neutral"
            size="sm"
            iconOnly={true}
            icon="refresh"
            label={props.retryLabel}
            disabled={props.disabled}
            onClick={() => props.onRetry?.()}
          />
        ) : null}
        <Button
          variant="ghost"
          tone="neutral"
          size="sm"
          iconOnly={true}
          icon="close"
          label={props.removeLabel}
          disabled={props.disabled}
          onClick={() => props.onRemove?.()}
        />
      </li>
    )
  })
}
